@kt.kernel
def k(x=kt.In(8, 32), s=kt.In(8), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            m = kt.unpack(kt.load(s[r : r + 4]))
            v = kt.load(x[r : r + 4, :])
            kt.store(y[r : r + 4, :], v * m)
